import java.io.*;

public class Main {
    static int n, totalCount, answer;
    static long[] sumArr = new long[15];
    static List<Integer>[] data = new ArrayList[15];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        for (int i = 0; i < 15; i++) {
            data[i] = new ArrayList<>();
        }
        build(0, 0);
        for (int i = 0; i <= 7; i++) {
            Collections.sort(data[i]);
        }
        totalCount = 0;
        answer = 0;
        for (int i = 1; i <= 9; i++) {
            search(i);
        }
        System.out.println(answer);
    }

    static void build(int level, int num) {
        if (level == 7) return;
        totalCount++;
        long val = ((long)(totalCount - num) % 998244353 + 998244353) % 998244353;
        data[level].add((int) val);
        sumArr[level] = (sumArr[level] + val) % 1000000007;
        for (int digit = 0; digit <= 9; digit++) {
            build(level + 1, num * 10 + digit);
        }
    }

    static void search(int x) {
        if (x > n) return;
        if (x * 1000000 + 999999 <= n && x * 10 * 1000000 > n) {
            int current = totalCount;
            for (int i = 0, mul = 1; i <= 6; i++, mul *= 10) {
                int sizeVec = data[i].size();
                long diffVal = ((long)(current - x * mul) % 998244353 + 998244353) % 998244353;
                int pos = lowerBound(data[i], (int)(1000000000 - diffVal));
                answer = (int)((answer + diffVal * sizeVec + sumArr[i]) % 1000000007);
                long subtractVal = (998244353L * (sizeVec - pos)) % 1000000007;
                answer = (int)((answer - subtractVal + 1000000007) % 1000000007);
                totalCount += sizeVec;
            }
            return;
        }
        totalCount++;
        long addVal = ((long)(totalCount - x) % 998244353 + 998244353) % 998244353;
        answer = (int)((answer + addVal) % 1000000007);
        for (int i = 0; i <= 9; i++) {
            search(x * 10 + i);
        }
    }

    static int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= target) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
